    @EventHandler
    public void on( DeleteConversionEventEvent event) {
    	ConversionEvent entity = new ConversionEvent();
   
    	// ------------------------------------------
    	// apply the ConversionEventId
    	// ------------------------------------------
    	entity.setConversionEventId( event.getConversionEventId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
